//go:build ignore
// +build ignore

package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func main() {
	goroot, err := exec.Command("go", "env", "GOROOT").Output()
	if err != nil {
		panic(fmt.Errorf("locating Go installation: %w", err))
	}
	path := filepath.Join(strings.TrimSpace(string(goroot)), "lib", "wasm", "wasm_exec.js")
	b, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}

	source := fmt.Sprintf(`//go:build !wasm

package app

// Code generated by go generate; DO NOT EDIT.

const wasmExecJSGoCurrent = %q
`, b)
	if err := os.WriteFile("wasmexec_gen.go", []byte(source), 0644); err != nil {
		panic(err)
	}
}
